-- Lot 203 : payloads 61 a 90 sur 150.
--
-- Un texte propre a chaque IA. Les commandes etant neuves, aucune version
-- courante n'existe : rien n'est retire, tout est pose.

drop table if exists lot_extension_payloads;
create temporary table lot_extension_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-351","moteur":"chatgpt","payload":"[RaccourcIA — /futurechild]\n\nMISSION\nCréez un enfant entièrement fictif inspiré de deux adultes consentants. Créer un portrait d’enfant fictif en combinant subtilement des indices visuels, sans prétention scientifique.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Confirmez-vous que les deux personnes acceptent cet usage de leurs portraits ? Puis, uniquement si encore nécessaire : Quel âge approximatif et quel style de rendu souhaitez-vous ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer un portrait d’enfant fictif en combinant subtilement des indices visuels, sans prétention scientifique. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 4:5; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nDiversité des traits, carnation plausible, naturel et cadre familial.\n\nÉVITER ET RESPONSABILITÉ\nAffirmer une prédiction génétique, sexualisation, biais de couleur de peau, adulte miniaturisé et ressemblance forcée. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 4:5, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"09dad9bee6d6337469b8bec14cc165f67669d725229a0b19acb5aca91e9a2f67"},{"ref":"RCI-IMG-351","moteur":"claude","payload":"[RaccourcIA — /futurechild]\n\nMISSION\nCréez un enfant entièrement fictif inspiré de deux adultes consentants. Créer un portrait d’enfant fictif en combinant subtilement des indices visuels, sans prétention scientifique.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, consolide-les sans longue reformulation et vérifie les capacités réellement disponibles avant de produire. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Confirmez-vous que les deux personnes acceptent cet usage de leurs portraits ? Puis, uniquement si encore nécessaire : Quel âge approximatif et quel style de rendu souhaitez-vous ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer un portrait d’enfant fictif en combinant subtilement des indices visuels, sans prétention scientifique. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 4:5; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nDiversité des traits, carnation plausible, naturel et cadre familial.\n\nÉVITER ET RESPONSABILITÉ\nAffirmer une prédiction génétique, sexualisation, biais de couleur de peau, adulte miniaturisé et ressemblance forcée. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 4:5, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"c0b163ea0135b59c4d8af8b5f5c935a410a7615598eb6f5af08bfda5accac537"},{"ref":"RCI-IMG-351","moteur":"gemini","payload":"[RaccourcIA — /futurechild]\n\nMISSION\nCréez un enfant entièrement fictif inspiré de deux adultes consentants. Créer un portrait d’enfant fictif en combinant subtilement des indices visuels, sans prétention scientifique.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte et relie chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Confirmez-vous que les deux personnes acceptent cet usage de leurs portraits ? Puis, uniquement si encore nécessaire : Quel âge approximatif et quel style de rendu souhaitez-vous ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer un portrait d’enfant fictif en combinant subtilement des indices visuels, sans prétention scientifique. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 4:5; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nDiversité des traits, carnation plausible, naturel et cadre familial.\n\nÉVITER ET RESPONSABILITÉ\nAffirmer une prédiction génétique, sexualisation, biais de couleur de peau, adulte miniaturisé et ressemblance forcée. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 4:5, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"a43928242bee83fd4a2220759219ab9b7462f4c7e92af551b789cfdeba6d7f40"},{"ref":"RCI-IMG-352","moteur":"chatgpt","payload":"[RaccourcIA — /twinsurprise]\n\nMISSION\nAjoutez à la scène un jumeau fictif reconnaissable mais doté d’un style distinct. Créer deux présences naturelles dans la même lumière, avec interaction crédible et différences contrôlées.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Le jumeau doit-il sembler presque identique ou afficher un style opposé ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 1 question sur toute l’exécution.\n\nEXÉCUTION\nCréer deux présences naturelles dans la même lumière, avec interaction crédible et différences contrôlées. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 4:5; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nIdentité, carnation, échelle, perspective et cohérence entre les deux versions.\n\nÉVITER ET RESPONSABILITÉ\nSimple duplication miroir, membres fusionnés, différence d’origine, visage instable et ombres incompatibles. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 4:5, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha